// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount, uint256 initialBalance) public {
        // Bound initialBalance to a reasonable range to avoid overflow issues
        vm.assume(initialBalance <= type(uint128).max);
        // Set up: give caller some balance and set MinSum to 0 so Collect is always allowed
        vm.deal(caller, initialBalance);
        c.SetMinSum(0);
        c.Initialized();
        // Pre-deposit so caller has a balance
        vm.prank(caller);
        c.Deposit{value: initialBalance}();
        // Get sum of all balances before Collect
        uint256 sumBefore = c.balances(caller);
        // Call Collect with a bounded amount
        vm.assume(amount <= type(uint128).max);
        vm.prank(caller);
        // We allow revert; we just need to check after call
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amount));
        // If call succeeded, sum should not have decreased
        if (ok) {
            uint256 sumAfter = c.balances(caller);
            assertTrue(sumAfter >= sumBefore, "Sum of balances decreased");
        } else {
            // If reverted, sum unchanged
            assertTrue(c.balances(caller) == sumBefore, "Sum changed on revert");
        }
    }
}

