pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Restrict depositAmount to avoid overflow in reference
        vm.assume(depositAmount < type(uint256).max / 2);
        // Ensure MinSum is low enough to allow Collect
        c.SetMinSum(1);
        c.Initialized();
        // Fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();
        uint256 balanceBefore = c.balances(caller);
        // bound collectAmount to be <= balanceBefore (to satisfy condition in reference)
        collectAmount = bound(collectAmount, 0, balanceBefore);
        // Execute Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        if (success) {
            uint256 balanceAfter = c.balances(caller);
            // In the reference, balances decrease by collectAmount; in the bug, they increase.
            // For any successful Collect, the caller's balance must be less than before.
            assertTrue(balanceAfter < balanceBefore, "Balance did not decrease after Collect");
        } else {
            // If Collect reverts, balances unchanged
            // Still, to have a clear rule for the reference, we can assert nothing.
            // But to avoid false failures, we just skip assertion when it reverts.
            assertTrue(true);
        }
    }
}

