pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        initialBalance = bound(initialBalance, 0, 100 ether);
        collectAmount = bound(collectAmount, 0, initialBalance);

        // Ensure the caller has at least MinSum to satisfy the condition
        uint256 minSum = 1 ether;
        vm.assume(initialBalance >= minSum);

        // Fund the contract and set caller's balance
        vm.deal(caller, initialBalance + collectAmount); // extra for gas
        vm.deal(address(c), initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record state before Collect
        uint256 callerBalanceInContractBefore = c.balances(caller);
        uint256 contractEthBefore = address(c).balance;

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Only consider successful calls (reference should always succeed here)
        if (success) {
            uint256 callerBalanceInContractAfter = c.balances(caller);
            uint256 contractEthAfter = address(c).balance;

            // The sum of the caller's balance in the contract plus the contract's ETH should remain invariant
            // because in the reference, the caller's balance decreases by collectAmount and the contract's ETH also decreases by collectAmount (sent to caller).
            // In the bug, the caller's balance increases, breaking this conservation.
            assertTrue(callerBalanceInContractBefore + contractEthBefore == callerBalanceInContractAfter + contractEthAfter);
        }
    }
}

