pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount, uint256 initialBalance, uint256 initialOtherBalance) public {
        // Assume the caller gets some ETH and we set initial balances
        vm.assume(caller != address(0));

        // Prepare: set MinSum to a small value, initialize the contract
        c.SetMinSum(0);
        c.Initialized();

        // Give the caller some balance via a direct deposit
        uint256 deposit = bound(initialBalance, 0, 100 ether);
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Give another address some balance (to have a second key to read)
        address other = address(0x1234);
        vm.deal(other, bound(initialOtherBalance, 0, 100 ether));
        vm.prank(other);
        c.Deposit{value: initialOtherBalance}();

        // Read balances before the Collect call
        uint256 balanceCallerBefore = c.balances(caller);
        uint256 balanceOtherBefore = c.balances(other);

        // Amount to collect
        uint256 am = bound(amount, 0, balanceCallerBefore);

        // Call Collect
        vm.prank(caller);
        c.Collect(am);

        // Read balances after
        uint256 balanceCallerAfter = c.balances(caller);
        uint256 balanceOtherAfter = c.balances(other);

        // The general rule: no address's balance should increase after a Collect call
        // But since Collect may revert (if amount > balanceCallerBefore), we need to handle that
        // Actually the require condition in Collect already checks balances[msg.sender] >= _am
        // So if amount > balanceCallerBefore, the call will revert and balances stay unchanged
        // We just check non-reverting case: if amount <= balanceCallerBefore
        if (am <= balanceCallerBefore) {
            // The caller's balance should not increase
            assertTrue(balanceCallerAfter <= balanceCallerBefore);
            // Other addresses' balances also should not increase
            assertTrue(balanceOtherAfter <= balanceOtherBefore);
        } else {
            // If reverting, balances are unchanged
            assertTrue(balanceCallerAfter == balanceCallerBefore);
            assertTrue(balanceOtherAfter == balanceOtherBefore);
        }
    }
}

