pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 minSum, uint256 deposit, uint256 collectAm) public {
        // Restrict inputs so the reference always succeeds
        vm.assume(minSum <= type(uint256).max / 2);
        vm.assume(deposit <= type(uint256).max / 2);
        vm.assume(collectAm <= deposit);

        // Setup: set MinSum and initialize
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund sender and deposit
        vm.deal(sender, deposit);
        vm.prank(sender);
        c.Deposit{value: deposit}();

        // Record total balance before Collect
        uint256 totalBefore = c.balances(sender) + address(c).balance;

        // Sender calls Collect
        vm.prank(sender);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAm));

        // Only proceed if call didn't revert
        vm.assume(ok);

        // Assert that total balances (all addresses + contract balance) did not increase
        uint256 totalAfter = c.balances(sender) + address(c).balance;
        assertTrue(totalAfter <= totalBefore);
    }
}

