pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        depositAmount = bound(depositAmount, 0.01 ether, 100 ether);
        collectAmount = bound(collectAmount, 0, depositAmount);

        // record balances before
        uint256 balCallerBefore = c.balances(caller);
        uint256 balOtherBefore = c.balances(other);

        // make a deposit to the caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool successDep,) = address(c).call{value: depositAmount}("");
        vm.assume(successDep);

        // record balances after deposit
        uint256 balCallerAfterDep = c.balances(caller);
        uint256 balOtherAfterDep = c.balances(other);

        // now call Collect (by the same caller)
        vm.prank(caller);
        (bool successCol,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // get balances after Collect
        uint256 balCallerAfterCol = c.balances(caller);
        uint256 balOtherAfterCol = c.balances(other);

        // general rule: the balance of any address should never decrease inexplicably
        // For the deposit effect, non-caller's balance should not change at all
        assertTrue(balOtherAfterDep == balOtherBefore && balOtherAfterCol == balOtherAfterDep, "Other balance changed unexpectedly");
        // For caller: after deposit, balance should increase; after Collect, it should not go below pre-deposit level
        assertTrue(balCallerAfterDep >= balCallerBefore, "Caller balance did not increase on deposit");
        if (successCol) {
            assertTrue(balCallerAfterCol >= balCallerBefore, "Caller balance decreased below original after Collect");
        } else {
            // on revert, balance unchanged from after deposit
            assertTrue(balCallerAfterCol == balCallerAfterDep, "Balance changed on failed Collect");
        }
    }
}

