pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount, uint256 minSum) public {
        // Bound inputs to reasonable ranges
        minSum = bound(minSum, 1 ether, 1000 ether);
        amount = bound(amount, 0, 1000 ether);

        // Initialize contract with a specific MinSum
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller with enough ether to potentially deposit
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        c.Deposit{value: 1 ether}();

        // Capture state before Collect
        uint256 balanceBefore = address(c).balance;
        uint256 callerBalanceBefore = c.balances(caller);

        // Attempt Collect from the caller
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amount));

        // Capture state after Collect
        uint256 balanceAfter = address(c).balance;
        uint256 callerBalanceAfter = c.balances(caller);

        // General rule: If caller's balance was less than MinSum, then Collect should revert
        // and balances should not change.
        if (callerBalanceBefore < minSum) {
            assertTrue(!success, "Collect should revert when balance < MinSum");
            assertTrue(balanceAfter == balanceBefore, "Contract balance should not change");
            assertTrue(callerBalanceAfter == callerBalanceBefore, "Caller balance should not change");
        } else {
            // If balance >= MinSum, then Collect may succeed only if amount <= balance
            // In reference, Collect only executes the transfer if amount <= balance.
            // We just check that contract balance does not increase (only decreases or stays same)
            // and that the change is consistent.
            if (success) {
                assertTrue(balanceAfter <= balanceBefore, "Contract balance should not increase");
                assertTrue(callerBalanceAfter == callerBalanceBefore - amount, "Caller balance should decrease by amount");
            } else {
                // If reverts, nothing changes
                assertTrue(balanceAfter == balanceBefore, "Contract balance unchanged on revert");
                assertTrue(callerBalanceAfter == callerBalanceBefore, "Caller balance unchanged on revert");
            }
        }
    }
}

