import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount, uint256 initialBalance, uint256 minSum) public {
        // Restrict inputs to avoid overflow and ensure valid state
        vm.assume(initialBalance >= amount);
        vm.assume(amount > 0);
        vm.assume(minSum <= initialBalance);
        vm.assume(caller != address(0));

        // Set up the contract state
        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(caller, initialBalance + amount); // enough to deposit and pay gas
