        // Since the reference decrements balances, and the mutant does not, this holds for reference but fails for mutant
        if (success) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore - amount, "Balance should decrease by amount");
        } else {
            // If it reverted, balance should remain unchanged
