pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow/revert in reference
        depositAmount = bound(depositAmount, 0, 1e30);
        collectAmount = bound(collectAmount, 0, 1e30);

        // Ensure caller has enough ETH and that MinSum is low enough so Collect condition can be met
        vm.deal(caller, 10 ether);
        vm.assume(collectAmount <= type(uint256).max / 2);

        // Initialize the contract and set MinSum to 0 so any balance >= 0 satisfies condition
        c.SetMinSum(0);
        c.Initialized();

        // Deposit funds from multiple addresses to create some balance
        address dummy = address(0xdead);
        vm.deal(dummy, depositAmount);
        vm.prank(dummy);
        c.Deposit{value: depositAmount}();

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record total balances before Collect
        uint256 totalBefore = c.balances(dummy) + c.balances(caller);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Record total balances after
        uint256 totalAfter = c.balances(dummy) + c.balances(caller);

        // General rule: if Collect succeeded and amount > 0, total balances decrease by exactly that amount
        if (success && collectAmount > 0) {
            assertTrue(totalAfter == totalBefore - collectAmount, "Total balances should decrease by collectAmount");
        } else {
            // Otherwise, balances unchanged (either revert or no-op due to conditions)
            assertTrue(totalAfter == totalBefore, "Balances unchanged if Collect didn't succeed");
        }
    }
}

