        uint256 balanceAfter = c.balances(sender);
        // General rule: If Collect succeeds, then the balance decreased exactly by withdrawAmount.
        // If it reverts, the balance is unchanged.
        // The original contract requires balances[sender] >= MinSum && balances[sender] >= withdrawAmount for success.
        // Mutant swaps the conditions, so the behavior might differ.
        // The assertion: success implies balanceAfter == balanceBefore - withdrawAmount.
